<?php
// Competitor portal: public links, and after logging in with their competition credentials, each competitor's
// own information to copy. Data: /etc/portal/portal.json, generated by competition.sh from config/main.json.

session_set_cookie_params([
    'httponly' => true,
    'secure' => ($_SERVER['HTTP_X_FORWARDED_PROTO'] ?? '') === 'https',
    'samesite' => 'Lax',
]);
session_start();

$data = json_decode(file_get_contents('/etc/portal/portal.json'), true);
$competitors = $data['competitors'];
$error = null;

if (empty($_SESSION['csrf'])) {
    $_SESSION['csrf'] = bin2hex(random_bytes(16));
}

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!hash_equals($_SESSION['csrf'], $_POST['csrf'] ?? '')) {
        http_response_code(400);
        exit('Requête invalide, rechargez la page.');
    }
    if (($_POST['action'] ?? '') === 'logout') {
        $_SESSION = [];
        session_destroy();
        header('Location: /', true, 303);
        exit;
    }
    $username = trim($_POST['username'] ?? '');
    $password = $_POST['password'] ?? '';
    $known = $competitors[$username] ?? null;
    if ($known !== null && hash_equals($known['password'], $password)) {
        session_regenerate_id(true);
        $_SESSION['user'] = $username;
        header('Location: /', true, 303);
        exit;
    }
    usleep(800000); // slows down password guessing
    $error = 'Identifiant ou mot de passe incorrect.';
}

$user = $_SESSION['user'] ?? null;
$me = $user !== null ? ($competitors[$user] ?? null) : null;
$repositories = $me !== null ? repositories($user, $me['password']) : null;

// Names of the repositories owned by the competitor in Gitea, asked with their own credentials (they see their
// private repositories, no admin token needed). Null when Gitea does not answer.
function repositories(string $user, string $password): ?array
{
    $context = stream_context_create(['http' => [
        'header' => 'Authorization: Basic ' . base64_encode($user . ':' . $password),
        'timeout' => 3,
        'ignore_errors' => true,
    ]]);
    $body = @file_get_contents(getenv('GITEA_API_URL') . '/user/repos?limit=100', false, $context);
    if ($body === false || !str_contains($http_response_header[0] ?? '', ' 200 ')) {
        return null;
    }
    $names = [];
    foreach (json_decode($body, true) ?? [] as $repository) {
        if (($repository['owner']['login'] ?? '') === $user) {
            $names[] = $repository['name'];
        }
    }
    return $names;
}

// Repository URL with the credentials, ready for "git clone": [shown (password hidden), copied (complete)]
function cloneUrl(string $repository, string $user, string $password): array
{
    $prefix = rawurlencode($user) . ':';
    $insert = fn(string $credentials) => preg_replace('#^(https?://)#', '${1}' . $credentials . '@', $repository);
    return [$insert($prefix . '••••••••'), $insert($prefix . rawurlencode($password))];
}

// A value shown one way and copied another (e.g. a password hidden on screen)
function copyableAs(string $shown, string $copied, bool $disabled = false): string
{
    return '<span class="cp"><code>' . e($shown) . '</code>'
        . iconButton('copy', $disabled ? "Créez d'abord le dépôt" : 'Copier', ICON_COPY,
            ' data-copy="' . e($copied) . '"' . ($disabled ? ' aria-disabled="true"' : ''))
        . '</span>';
}

function e($value): string
{
    return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
}

const ICON_COPY = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><rect x="9" y="9" width="12" height="12" rx="2"/><path d="M5 15H4a1 1 0 0 1-1-1V4a1 1 0 0 1 1-1h10a1 1 0 0 1 1 1v1"/></svg>';
const ICON_EYE = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.6-7 10-7 10 7 10 7-3.6 7-10 7S2 12 2 12z"/><circle cx="12" cy="12" r="3"/></svg>';

const ICON_OPEN = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M14 4h6v6"/><path d="M10 14 20 4"/><path d="M19 14v5a1 1 0 0 1-1 1H5a1 1 0 0 1-1-1V6a1 1 0 0 1 1-1h5"/></svg>';
const ICON_LOGOUT = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4"/><path d="m16 17 5-5-5-5"/><path d="M21 12H9"/></svg>';

// Icon button with a tooltip (data-tip, shown on hover and keyboard focus)
function iconButton(string $class, string $tip, string $icon, string $attributes = ''): string
{
    return '<button type="button" class="icon-btn ' . $class . '" data-tip="' . e($tip) . '" aria-label="' . e($tip)
        . '"' . $attributes . '>' . $icon . '</button>';
}

// A value with a copy button (a secret is hidden until "Afficher")
function copyable($value, bool $secret = false): string
{
    $v = e($value);
    $shown = $secret ? '<span class="secret" data-value="' . $v . '">••••••••</span>'
        . iconButton('reveal', 'Afficher', ICON_EYE) : '<code>' . $v . '</code>';
    return '<span class="cp">' . $shown . iconButton('copy', 'Copier', ICON_COPY, ' data-copy="' . $v . '"') . '</span>';
}
